//! 👁️ DWG visual style properties retain each value and its independent operation.
use semio_framework_value::{ValueError,ValueRefusalKind};
use super::super::*;
use super::number::{Projection,Row};
use super::color;
use super::reader::{boolean,unsigned,word,Reader};
use semio_framework_os_kernel::sqlite_snapshot::artifact::Cell::{Integer as I,Text as T,Real as R};

fn op(v:DwgVisualStylePropertyOperation)->&'static str{match v{DwgVisualStylePropertyOperation::Inherit=>"inherit",DwgVisualStylePropertyOperation::Set=>"set",DwgVisualStylePropertyOperation::Disable=>"disable",DwgVisualStylePropertyOperation::Enable=>"enable"}}
fn read_op(v:&str)->Result<DwgVisualStylePropertyOperation,ValueError>{match v{"inherit"=>Ok(DwgVisualStylePropertyOperation::Inherit),"set"=>Ok(DwgVisualStylePropertyOperation::Set),"disable"=>Ok(DwgVisualStylePropertyOperation::Disable),"enable"=>Ok(DwgVisualStylePropertyOperation::Enable),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"DWG visual property operation is unknown"))}}
fn int(row:Row<'_>,c:usize)->Result<DwgVisualStyleProperty<u32>,ValueError>{Ok(DwgVisualStyleProperty{value:unsigned(row,c)?,operation:read_op(row.text(c+1)?)?})}
fn num(row:Row<'_>,c:usize)->Result<DwgVisualStyleProperty<f64>,ValueError>{Ok(DwgVisualStyleProperty{value:row.real(c)?,operation:read_op(row.text(c+1)?)?})}
pub(super) fn project(p:&mut Projection<'_,'_>,id:i64,v:&DwgVisualStyle)->Result<(),ValueError>{
 p.insert_key("dwg_visual_style",id,&[T(&v.description),I(i64::from(v.style_type)),I(i64::from(v.extension_lighting_model)),I(i64::from(v.internal_only))])?;let v=&v.properties;
 p.insert_key("dwg_visual_style_face",id,&[I(i64::from(v.face_lighting_model.value)),T(op(v.face_lighting_model.operation)),I(i64::from(v.face_lighting_quality.value)),T(op(v.face_lighting_quality.operation)),I(i64::from(v.face_color_mode.value)),T(op(v.face_color_mode.operation)),I(i64::from(v.face_modifiers.value)),T(op(v.face_modifiers.operation)),R(v.face_opacity.value),T(op(v.face_opacity.operation)),R(v.face_specular_amount.value),T(op(v.face_specular_amount.operation)),T(op(v.face_monochrome_color.operation))])?;
 p.insert_key("dwg_visual_style_edge",id,&[I(i64::from(v.edge_model.value)),T(op(v.edge_model.operation)),I(i64::from(v.edge_styles.value)),T(op(v.edge_styles.operation)),T(op(v.edge_intersection_color.operation)),T(op(v.edge_obscured_color.operation)),I(i64::from(v.edge_obscured_line_pattern.value)),T(op(v.edge_obscured_line_pattern.operation)),I(i64::from(v.edge_intersection_line_pattern.value)),T(op(v.edge_intersection_line_pattern.operation)),R(v.edge_crease_angle.value),T(op(v.edge_crease_angle.operation)),I(i64::from(v.edge_modifiers.value)),T(op(v.edge_modifiers.operation)),T(op(v.edge_color.operation)),R(v.edge_opacity.value),T(op(v.edge_opacity.operation)),I(i64::from(v.edge_width.value)),T(op(v.edge_width.operation)),I(i64::from(v.edge_overhang.value)),T(op(v.edge_overhang.operation)),I(i64::from(v.edge_jitter.value)),T(op(v.edge_jitter.operation)),T(op(v.edge_silhouette_color.operation)),I(i64::from(v.edge_silhouette_width.value)),T(op(v.edge_silhouette_width.operation)),I(i64::from(v.edge_halo_gap.value)),T(op(v.edge_halo_gap.operation)),I(i64::from(v.edge_isolines.value)),T(op(v.edge_isolines.operation)),I(i64::from(v.hidden_edge_precision.value)),T(op(v.hidden_edge_precision.operation))])?;
 p.insert_key("dwg_visual_style_display",id,&[I(i64::from(v.display_settings.value)),T(op(v.display_settings.operation)),R(v.display_brightness.value),T(op(v.display_brightness.operation)),I(i64::from(v.display_shadow_type.value)),T(op(v.display_shadow_type.operation))])?;
 color::project(p,"dwg_visual_face_monochrome_color",id,&v.face_monochrome_color.value)?;color::project(p,"dwg_visual_edge_intersection_color",id,&v.edge_intersection_color.value)?;color::project(p,"dwg_visual_edge_obscured_color",id,&v.edge_obscured_color.value)?;color::project(p,"dwg_visual_edge_color",id,&v.edge_color.value)?;color::project(p,"dwg_visual_edge_silhouette_color",id,&v.edge_silhouette_color.value)
}
pub(super) fn reconstruct(r:&mut Reader<'_,'_,'_>,id:i64)->Result<DwgVisualStyle,ValueError>{
 let root=r.component("dwg_visual_style",id)?;let face=r.component("dwg_visual_style_face",id)?;let edge=r.component("dwg_visual_style_edge",id)?;let display=r.component("dwg_visual_style_display",id)?;
 Ok(DwgVisualStyle{description:root.text(1)?.into(),style_type:unsigned(root,2)?,extension_lighting_model:word(root,3)?,internal_only:boolean(root,4)?,properties:DwgVisualStyleProperties{
 face_lighting_model:int(face,1)?,face_lighting_quality:int(face,3)?,face_color_mode:int(face,5)?,face_modifiers:DwgVisualStyleProperty{value:word(face,7)?,operation:read_op(face.text(8)?)?},face_opacity:num(face,9)?,face_specular_amount:num(face,11)?,face_monochrome_color:DwgVisualStyleProperty{value:color::reconstruct(r,"dwg_visual_face_monochrome_color",id)?,operation:read_op(face.text(13)?)?},
 edge_model:int(edge,1)?,edge_styles:int(edge,3)?,edge_intersection_color:DwgVisualStyleProperty{value:color::reconstruct(r,"dwg_visual_edge_intersection_color",id)?,operation:read_op(edge.text(5)?)?},edge_obscured_color:DwgVisualStyleProperty{value:color::reconstruct(r,"dwg_visual_edge_obscured_color",id)?,operation:read_op(edge.text(6)?)?},
 edge_obscured_line_pattern:int(edge,7)?,edge_intersection_line_pattern:int(edge,9)?,edge_crease_angle:num(edge,11)?,edge_modifiers:int(edge,13)?,edge_color:DwgVisualStyleProperty{value:color::reconstruct(r,"dwg_visual_edge_color",id)?,operation:read_op(edge.text(15)?)?},edge_opacity:num(edge,16)?,edge_width:int(edge,18)?,edge_overhang:int(edge,20)?,edge_jitter:int(edge,22)?,edge_silhouette_color:DwgVisualStyleProperty{value:color::reconstruct(r,"dwg_visual_edge_silhouette_color",id)?,operation:read_op(edge.text(24)?)?},edge_silhouette_width:int(edge,25)?,edge_halo_gap:int(edge,27)?,edge_isolines:int(edge,29)?,hidden_edge_precision:DwgVisualStyleProperty{value:boolean(edge,31)?,operation:read_op(edge.text(32)?)?},
 display_settings:int(display,1)?,display_brightness:num(display,3)?,display_shadow_type:int(display,5)?
 }})
}
